select coalesce(jsonb_agg(t.failed),'[]'::jsonb)as failures from (select 'shared:official:equipment:es:d9b601a829486f58d1edab2a' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d9b601a829486f58d1edab2a' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_765086698ac323cb$[{"id":"official-base-table","rows":[["Guja","20 po","6 lb","1d10 cortante","+0","Pesada, Gran alcance, A dos manos"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-heavy","text":"Pesada. Las criaturas Pequeñas tienen desventaja en las tiradas de ataque con armas pesadas. Su tamaño y peso hacen que sean demasiado voluminosas para que una criatura Pequeña las use con efectividad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-reach","text":"Gran alcance. Cuando empleas un arma de este tipo, tu alcance aumenta en 1,5 m, tanto al atacar como a efectos de ataques de oportunidad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_765086698ac323cb$::jsonb) union all select 'shared:official:equipment:es:d9e9a9a6ad6074aa856fdb75' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:d9e9a9a6ad6074aa856fdb75' and payload#>'{features}'=$verify_818805f0ac1beb2b$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, tendrás ventaja en las tiradas de salvación contra cualquier conjuro que solo te haga objetivo a ti (no como parte de un área de efecto). Además, si sacas un 20 en la tirada de salvación y el conjuro es de nivel 7 o inferior, el conjuro no tendrá efecto alguno en ti y, en su lugar, hará objetivo al lanzador y utilizará el nivel del espacio de conjuro, la CD de salvación de conjuros, el bonificador de ataque y la aptitud mágica del lanzador.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_818805f0ac1beb2b$::jsonb) union all select 'shared:official:equipment:es:da3415c797431ef012a27635' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:da3415c797431ef012a27635' and payload#>'{features}'=$verify_49e3e80c25fd1c94$[{"id":"lance-special","kind":"other","name":"Uso de la lanza de caballería","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.\n\nRequiere dos manos si no se está montado.\n\nDuración: Mientras se utiliza el arma..","showInActions":false}]$verify_49e3e80c25fd1c94$::jsonb) union all select 'shared:official:equipment:es:daca2184e53f2ea25df94b05' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:daca2184e53f2ea25df94b05' and payload#>'{features}'=$verify_ad0db3441d684050$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este yelmo, podrás utilizar una acción para lanzar el conjuro detectar pensa- mientos (CD de salvación 13) desde él. Mientras mantengas la concentración en el conjuro, podrás usar una acción adicional para mandar un mensaje telepático a una criatura en la que te estés concen- trando. Podrá responderte usando una acción adicional mientras te concentres en ella.\n\nMientras te concentres en una criatura con detectar pensamientos, podrás utilizar una acción para lanzar el conjuro sugestión (CD de salvación 13) desde el yelmo sobre esa criatura. Una vez utilizada, la propiedad sugestión no puede volver a usarse hasta el siguiente amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_ad0db3441d684050$::jsonb) union all select 'shared:official:equipment:es:db68a706e3edbdffed736118' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:db68a706e3edbdffed736118' and payload#>'{features}'=$verify_7ee10a6b1ec9aba7$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves estos guantes, nadar y escalar no te costará movimiento adicional y obtendrás un bonificador de +5 a las pruebas de Fuerza (Atletismo) que hagas para nadar o escalar.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_7ee10a6b1ec9aba7$::jsonb) union all select 'shared:official:equipment:es:db7d1b79dc665d3f57d5d2c2' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:db7d1b79dc665d3f57d5d2c2' and payload#>'{features}'=$verify_dde479bbe9eae2a6$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta botella de latón pintado pesa 0,5 kg. Cuando uses una acción para quitar el tapón, una nube de humo denso saldrá de la botella. Al final de tu turno, el humo desaparece con un fogonazo inofensivo y un ifrit se manifestará en un espacio sin ocupar a 9 m o menos de ti.\n\nLa primera vez que se abra la botella, tu GM tirará para determina lo que ocurre.\n\n01–10 · El ifrit te ataca. Tras luchar durante 5 asaltos, el ifrit desaparecerá y la botella perderá su magia.\n11–90 · El ifrit te sirve durante 1 hora y hace lo que le ordenes. A continuación, regresará a la botella y un nuevo tapón le impedirá salir. El tapón no se puede quitar durante 24 horas. Las dos siguientes veces que se abra la botella, ocurrirá el mismo efecto. Si la botella se abre una cuarta vez, el ifrit se escapará y desaparecerá, y la botella perderá su magia.\n91–00 · El ifrit puede lanzar el conjuro deseo tres veces para ti. Desaparecerá cuando conceda el último deseo o después de 1 hora y la botella perderá su magia.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_dde479bbe9eae2a6$::jsonb) union all select 'shared:official:equipment:es:db828358f6811c9a673a2d57' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:db828358f6811c9a673a2d57' and payload#>'{features}'=$verify_1c4fc0657463d9e9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"El humo se filtra a través del tapón de plomo de esta botella de latón, que pesa 0,5 kg. Cuando uses una acción para quitar el tapón, una nube de humo denso saldrá de la botella y cubrirá un radio de 18 m. La zona que ocupa la nube estará muy oscura. Cada minuto que la botella permanezca abierta y dentro de la nube, el radio aumentará en 3 m hasta que alcance su máximo de 36 m.\n\nLa nube permanecerá mientras la botella esté abierta. Para cerrarla, tienes que utilizar una acción para pronunciar su palabra de activación. Una vez que se cierre la botella, la nube se disipará tras 10 minutos. Un viento moderado (de 15 a 30 km/h) también puede dispersar el humo en 1 minuto y un viento fuerte (más de 30 km/h) lo hará en 1 asalto.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_1c4fc0657463d9e9$::jsonb) union all select 'shared:official:equipment:es:dbdd04e383a8cd140b7f0c66' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:dbdd04e383a8cd140b7f0c66' and payload#>'{features}'=$verify_39b77e31a352c43e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este aceite transparente y gelatinoso brilla debido a las minúsculas esquirlas de plata que contiene. Puede impregnar un arma cortante o perforante o hasta 5 unidades de munición cortante o perforante. Aplicar el aceite lleva 1 minuto. Durante 1 hora, el objeto impregnado es mágico y tiene un bonificador de +3 a las tiradas de ataque y de daño.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$verify_39b77e31a352c43e$::jsonb) union all select 'shared:official:equipment:es:dca7ce044bc3a61a7d7975a9' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:dca7ce044bc3a61a7d7975a9' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_e79cf78b61c71d5c$[{"id":"official-base-table","rows":[["Garrote grande","2 pp","10 lb","1d8 contundente","+0","A dos manos"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_e79cf78b61c71d5c$::jsonb) union all select 'shared:official:equipment:es:ddb03c90d649ff901a595dfd' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:ddb03c90d649ff901a595dfd' and payload#>'{features}'=$verify_a5c1642dce15fd53$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras embraces este escudo, tendrás ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos, y los ataques de conjuro tendrán desventaja contra ti.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_a5c1642dce15fd53$::jsonb) union all select 'shared:official:equipment:es:dfac5d1193ee8763411386fa' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:dfac5d1193ee8763411386fa' and payload#>'{features}'=$verify_7bc718f5417070c9$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cada uno de los tres compartimentos de esta aljaba está conectado con un espacio extradimensional, lo que le permite contener muchos objetos sin pesar nunca más de 1 kg. El compartimento más pequeño puede albergar hasta 60 flechas, virotes u objetos similares. El compartimento intermedio puede contener hasta 18 jabalinas u objetos parecidos. En el compartimento más grande caben hasta 6 objetos largos, como arcos, bastones o lanzas.\n\nPuedes extraer cualquier objeto que contenga esta aljaba igual que lo harías con una aljaba o vaina normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_7bc718f5417070c9$::jsonb) union all select 'shared:official:equipment:es:dfe4f67404619490ab853e9d' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:dfe4f67404619490ab853e9d' and payload#>'{features}'=$verify_f0e511db536bffb9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Los puntos de golpe perdidos por el daño de esta arma solo pueden recuperarse mediante un descanso corto o largo, no mediante la regeneración, la magia o cualquier otro medio.\n\nUna vez por turno, cuando impactes a una criatura con un ataque usando esta arma mágica, podrás herirla. Al principio de cada turno de la criatura herida, sufrirá 1d4 de daño necrótico por cada vez que la hayas herido y luego podrá realizar una tirada de salvación de Constitución con CD 15 para acabar con el efecto de esas heridas si la supera. Como alternativa, la criatura herida u otra que se encuentre a 1,5 m o menos de ella podrá usar una acción para realizar una prueba de Sabiduría (Medicina) con CD 15 y acabar con el efecto de las heridas si la supera.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f0e511db536bffb9$::jsonb) union all select 'shared:official:equipment:es:e14cde6c9aac3e864c054708' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:e14cde6c9aac3e864c054708' and payload#>'{features}'=$verify_098e651649ff7d4d$[{"id":"mundane-assisted-use","kind":"other","name":"Jugar con competencia","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Set de Juego. Este objeto engloba un amplio rango de piezas de juego incluyendo dados y barajas de cartas (para juegos tales como Tres dragones). Unos pocos ejemplos comunes aparecen en la tabla Herramientas pero existen otro tipo de sets de juego. Si eres competente con un set de juego puedes añadir tu bonificador de competencia a las pruebas de característica que realices para jugar a un juego con este set. Cada tipo de set de juego requiere una competencia por separado.\n\nDuración: Según su uso..","showInActions":false}]$verify_098e651649ff7d4d$::jsonb) union all select 'shared:official:equipment:es:e195a30cf2bed9617cab705d' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:e195a30cf2bed9617cab705d' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_fceb5fda75291662$[{"id":"official-base-table","rows":[["Martillo ligero","2 po","2 lb","1d4 contundente","+0","Ligera, Arrojadiza","20/60"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_fceb5fda75291662$::jsonb) union all select 'shared:official:equipment:es:e22d639500fbb1d59085b9a5' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:e22d639500fbb1d59085b9a5' and payload#>'{features}'=$verify_9695271bece60149$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa, tendrás ventaja en las tiradas de salvación contra conjuros.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_9695271bece60149$::jsonb) union all select 'shared:official:equipment:es:e2c6fc0f3a4001fca0154c52' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:e2c6fc0f3a4001fca0154c52' and payload#>'{description}'=$verify_29de674beabfb97f$"Objeto · Precio base · Peso\nFuego de alquimista (frasco) · 50 po · 1 lb\n\nFuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_29de674beabfb97f$::jsonb and payload#>'{features}'=$verify_e827c91874ef8602$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Fuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_e827c91874ef8602$::jsonb and payload#>'{rules,definition,description}'=$verify_fc80bfec3e404bfa$[{"id":"official-table","rows":[["Fuego de alquimista (frasco)","50 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Fuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_fc80bfec3e404bfa$::jsonb) union all select 'shared:official:equipment:es:e3acaffca731d7c31f0bfeff' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:e3acaffca731d7c31f0bfeff' and payload#>'{features}'=$verify_12efb51145f6de93$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para colocar este cubo metálico de 2,5 cm de lado en el suelo y pronunciar su palabra de activación. El cubo se convertirá rápidamente en una fortaleza que permanecerá hasta que emplees una acción para pronunciar la palabra de activación que la hace desaparecer, que solo funcionará si la fortaleza está vacía.\n\nEsta fortificación es una torre cuadrada de 6 m de lado y 9 m de altura, con aspilleras en todos los lados y almenas en la parte superior. Su interior se divide en dos plantas conectadas mediante una escalera que recorre una de las paredes. La escalera termina en una trampilla que conduce al tejado. Cuando se activa, la torre tiene una puerta pequeña en el lado que mira hacia ti. La puerta se abre solo bajo tus órdenes, que puedes dar como acción adicional. Es inmune al conjuro abrir y otros efectos mágicos similares, como el de un carillón de apertura.\n\nTodas las criaturas situadas en la zona en la que aparezca la fortaleza deberán realizar una tirada de salvación de Destreza con CD 15; sufrirán 10d10 de daño contundente si la fallan o la mitad del daño si la superan. En ambos casos, cada criatura será empujada a un espacio sin ocupar junto a la fortaleza, pero fuera de ella. Los objetos situados en la zona y que no lleve o vista alguien sufrirán este daño y serán empujados automáticamente.\n\nLa torre está hecha de adamantina y su magia impide que la derriben. El tejado, la puerta y las paredes tienen 100 puntos de golpe cada uno, inmunidad al daño de armas no mágicas (salvo armas de asedio) y resistencia al resto de daño. Solo un conjuro deseo puede reparar la fortaleza (este uso cuenta como replicar un conjuro de nivel 8 o inferior). Cada vez que se lance deseo, el tejado, la puerta o una pared recuperará 50 puntos de golpe.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_12efb51145f6de93$::jsonb) union all select 'shared:official:equipment:es:e59b07ec950530f903759662' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:e59b07ec950530f903759662' and payload#>'{features}'=$verify_bdb52a76377c1eea$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a un objeto con esta espada mágica e impactes, toma el resultado máximo de los dados de daño del arma contra el objetivo.\n\nCuando ataques a una criatura con esta arma y saques un 20 en la tirada de ataque, el objetivo sufrirá 4d6 de daño cortante adicional. A continuación, tira otro d20. Si sacas un 20, seccionarás uno de los miembros del objetivo. Tu GM determinará el efecto de esta amputación. Si la criatura no tiene ningún miembro que se pueda amputar, en vez de ello, seccionarás otra parte de su cuerpo.\n\nAdemás, puedes pronunciar la palabra de activación de la espada para hacer que la hoja emita luz brillante en un radio de 3 m y luz tenue 3 m más allá. Si vuelves a pronunciar la palabra de activación o envainas la espada, apagarás la luz.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_bdb52a76377c1eea$::jsonb) union all select 'shared:official:equipment:es:e6f279561dbf73cf66121000' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:e6f279561dbf73cf66121000' and payload#>'{features}'=$verify_74bbd0eb847ed37e$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesta esta capa, podrás utilizar una acción para pronunciar su palabra de activación. La capa se convertirá en unas alas de murciélago o de pájaro que se colocan a tu espalda durante 1 hora o hasta que repitas la palabra de activación como acción. Las alas te otorgan una velocidad volando de 18 m. Cuando desaparezcan, no podrás usarlas de nuevo durante 1d12 horas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_74bbd0eb847ed37e$::jsonb) union all select 'shared:official:equipment:es:e6fb55a58513814680574185' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:e6fb55a58513814680574185' and payload#>'{features}'=$verify_66537621eea405a8$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene indicaciones para influir y embelesar a los demás, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Carisma aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_66537621eea405a8$::jsonb) union all select 'shared:official:equipment:es:e71f1a3639d0ca163bea1a3f' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:e71f1a3639d0ca163bea1a3f' and payload#>'{features}'=$verify_d20dc719ee200707$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 de sus cargas para lanzar el conjuro telaraña (CD de salvación 15) desde ella.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_d20dc719ee200707$::jsonb) union all select 'shared:official:equipment:es:e994633540f2d0f6fe235b6b' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:e994633540f2d0f6fe235b6b' and payload#>'{features}'=$verify_dd50717b3781ab10$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes con un ataque usando esta espada mágica, el objetivo recibirá 1d6 de daño de frío adicional. Además, mientras empuñes la espada, tendrás resistencia al daño de fuego.\n\nEn temperaturas bajo cero, la espada emite luz brillante en un radio de 3 m y luz tenue 3 m más allá.\n\nCuando desenvainas esta arma, puedes extinguir todas las llamas no mágicas que haya a 9 m o menos de ti. Esta propiedad no puede emplearse más de una vez por hora.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_dd50717b3781ab10$::jsonb) union all select 'shared:official:equipment:es:ea969a49b5350a175ac19b83' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:ea969a49b5350a175ac19b83' and payload#>'{features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_4543b46f281f3b43$::jsonb and payload#>'{rules,definition,description}'=$verify_36fbd84554054a1f$[{"id":"official-base-table","rows":[["Daga","2 po","1 lb","1d4 perforante","+0","Sutil, Ligera, Arrojadiza","20/60"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_36fbd84554054a1f$::jsonb) union all select 'shared:official:equipment:es:eb25c4df5d5bd294667b7d08' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:eb25c4df5d5bd294667b7d08' and payload#>'{features}'=$verify_7f63cdf0190e902c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este tridente es un arma mágica. Tiene 3 cargas. Mientras lo lleves contigo, podrás utilizar una acción y gastar 1 carga para lanzar dominar bestia (CD de salvación 15) desde él sobre una bestia que tenga una velocidad nadando innata. El tridente recupera 1d3 cargas empleadas cada día, al amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_7f63cdf0190e902c$::jsonb) union all select 'shared:official:equipment:es:ee49205d290ab9eaafa1108f' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:ee49205d290ab9eaafa1108f' and payload#>'{features}'=$verify_37d3cb15a9648010$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este yelmo, podrás utilizar una acción para lanzar a voluntad el conjuro entender idiomas desde él.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_37d3cb15a9648010$::jsonb) union all select 'shared:official:equipment:es:ef95f23bd99224f3cdf64a7d' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:ef95f23bd99224f3cdf64a7d' and payload#>'{features}'=$verify_4548fbeea826434d$[{"id":"store-spells","kind":"other","name":"Almacenar un conjuro","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo almacena los conjuros que se lanzan sobre él y los conserva hasta que el portador sintonizado decida usarlos. El anillo puede guardar conjuros con un valor de hasta 5 niveles. Cuando lo encuentres, contendrá 1d6 − 1 niveles de conjuros almacenados, a elección de tu GM.\n\nCualquier criatura puede lanzar un conjuro de niveles 1 a 5 sobre el anillo si lo toca mientras lanza el conjuro. El único efecto que tendrá el conjuro es que quedará almacenado en el anillo. Si el anillo no puede albergarlo, el conjuro se gastará sin efecto. El nivel del espacio utilizado para lanzar el conjuro determina cuánto espacio utiliza.\n\nMientras lleves puesto este anillo, podrás lanzar cualquiera de los conjuros almacenados. El conjuro utiliza el nivel del espacio, la CD de salvación de conjuros, el bonificador de ataque de conjuros y la aptitud mágica del lanzador original, pero, por lo demás, funciona como si tú lo hubieses lanzado. El conjuro lanzado desde el anillo deja de estar almacenado en él, por lo que deja espacio libre.\n\nDuración: Hasta lanzar el conjuro almacenado..","showInActions":false},{"id":"cast-stored-spell","kind":"other","name":"Lanzar un conjuro almacenado","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo almacena los conjuros que se lanzan sobre él y los conserva hasta que el portador sintonizado decida usarlos. El anillo puede guardar conjuros con un valor de hasta 5 niveles. Cuando lo encuentres, contendrá 1d6 − 1 niveles de conjuros almacenados, a elección de tu GM.\n\nCualquier criatura puede lanzar un conjuro de niveles 1 a 5 sobre el anillo si lo toca mientras lanza el conjuro. El único efecto que tendrá el conjuro es que quedará almacenado en el anillo. Si el anillo no puede albergarlo, el conjuro se gastará sin efecto. El nivel del espacio utilizado para lanzar el conjuro determina cuánto espacio utiliza.\n\nMientras lleves puesto este anillo, podrás lanzar cualquiera de los conjuros almacenados. El conjuro utiliza el nivel del espacio, la CD de salvación de conjuros, el bonificador de ataque de conjuros y la aptitud mágica del lanzador original, pero, por lo demás, funciona como si tú lo hubieses lanzado. El conjuro lanzado desde el anillo deja de estar almacenado en él, por lo que deja espacio libre.\n\nDuración: Según el conjuro almacenado..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_4548fbeea826434d$::jsonb) union all select 'shared:official:equipment:es:efcf9190471450b926304709' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:efcf9190471450b926304709' and payload#>'{description}'=$verify_1b9f73811a287e94$"Objeto · Precio base · Peso\nRopas de calidad · 15 po · 6 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_1b9f73811a287e94$::jsonb and payload#>'{rules,definition,description}'=$verify_44789f9e192f265d$[{"id":"official-table","rows":[["Ropas de calidad","15 po","6 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_44789f9e192f265d$::jsonb) union all select 'shared:official:equipment:es:f04899b83f054b78715736ed' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f04899b83f054b78715736ed' and payload#>'{features}'=$verify_6adf0937c2fb14b1$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro describe diferentes ejercicios para mantenerse en forma y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Fuerza aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_6adf0937c2fb14b1$::jsonb) union all select 'shared:official:equipment:es:f16f5c78093a9e8470217e65' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f16f5c78093a9e8470217e65' and payload#>'{features}'=$verify_a6c587cf49df5be5$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta cuerda de seda de 18 m de longitud pesa 1,5 kg y puede soportar hasta 1500 kg. Si sujetas uno de los extremos de la cuerda y utilizas una acción para pronunciar la palabra de activación, la cuerda cobrará vida. Como acción adicional, puedes ordenar al otro extremo que se mueva hacia un destino que elijas. Ese extremo se moverá 3 m en tu turno cuando le des la orden por primera vez y 3 m en cada uno de tus turnos hasta que llegue a su destino, hasta que alcance su longitud máxima o hasta que le mandes parar. También puedes ordenar a la cuerda que se ate de forma segura a un objeto, se desate, se anude o se desanude, o se enrolle para transportarla.\n\nSi le ordenas que se anude, se formarán unos nudos grandes en intervalos de 30 cm a lo largo de la cuerda. Mientras esté anudada, la cuerda reduce su longitud a 15 m y otorga ventaja en las pruebas que se realicen para escalarla.\n\nLa cuerda tiene una CA de 20 y 20 puntos de golpe. Recupera 1 punto de golpe cada 5 minutos mientras tenga al menos 1 punto de golpe. Si los puntos de golpe de la cuerda se reducen a 0, se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_a6c587cf49df5be5$::jsonb) union all select 'shared:official:equipment:es:f2e134338fbb17f190d3f817' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f2e134338fbb17f190d3f817' and payload#>'{description}'=$verify_08989937f975ed3b$"Objeto · Precio base · Peso\nOrbe · 20 po · 3 lb\n\nCanalizador arcano. Un canalizador arcano es un objeto especial, diseñado para conducir el poder de los conjuros arcanos. Puede ser un orbe, un cristal, un cetro, un bastón fabricado específicamente con este fin, un trozo de madera con forma de varita o un objeto similar. Los brujos, hechiceros y magos pueden utilizar este objeto como canalizador mágico.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_08989937f975ed3b$::jsonb and payload#>'{features}'=$verify_7f0fd4e9063deb6a$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Canalizador arcano. Un canalizador arcano es un objeto especial, diseñado para conducir el poder de los conjuros arcanos. Puede ser un orbe, un cristal, un cetro, un bastón fabricado específicamente con este fin, un trozo de madera con forma de varita o un objeto similar. Los brujos, hechiceros y magos pueden utilizar este objeto como canalizador mágico.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_7f0fd4e9063deb6a$::jsonb and payload#>'{rules,definition,description}'=$verify_528ba96b62b1dcb8$[{"id":"official-table","rows":[["Orbe","20 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Canalizador arcano. Un canalizador arcano es un objeto especial, diseñado para conducir el poder de los conjuros arcanos. Puede ser un orbe, un cristal, un cetro, un bastón fabricado específicamente con este fin, un trozo de madera con forma de varita o un objeto similar. Los brujos, hechiceros y magos pueden utilizar este objeto como canalizador mágico.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_528ba96b62b1dcb8$::jsonb) union all select 'shared:official:equipment:es:f3000567c773f6c02cfb2957' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f3000567c773f6c02cfb2957' and payload#>'{features}'=$verify_b5311f5ea949dadf$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción para poner estos grilletes a una criatura incapacitada. Se ajustan a criaturas de tamaños Pequeño a Grande. Además de servir como unas esposas normales, los grilletes impiden que la criatura utilice cualquier método de movimiento extradimensional, incluidos la teletransportación o los viajes a otro plano de existencia. No impiden que la criatura atraviese un portal interdimensional.\n\nTú y cualquier criatura que designes al usar los grilletes podéis emplear una acción para quitarlos. Una vez cada 30 días, la criatura esposada podrá realizar una prueba de Fuerza (Atletismo) con CD 30. Si la supera, se liberará y destruirá los grilletes.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_b5311f5ea949dadf$::jsonb) union all select 'shared:official:equipment:es:f3814673135c5a3a0681325d' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f3814673135c5a3a0681325d' and payload#>'{features}'=$verify_78cacd5c998f65d7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo está vinculado a uno de los cuatro Planos Elementales. Tu GM elige el plano o lo determina al azar.\n\nMientras lo lleves puesto, tendrás ventaja en las tiradas de ataque contra elementales del plano vinculado y ellos tendrán desventaja en las tiradas de ataque contra ti. Además, tendrás acceso a ciertas propiedades en función del plano vinculado.\n\nEl anillo tiene 5 cargas. Recupera 1d4 +1 cargas empleadas cada día, al amanecer. Los conjuros lanzados desde el anillo tienen una CD de salvación de 17.\n\nAnillo de comandar elementales de agua. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de agua. Además, puedes permanecer de pie sobre superficies líquidas y andar por ellas como si fueran terreno firme. También puedes hablar y entender acuano.\n\nSi ayudas a matar a un elemental de agua mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Puedes respirar bajo el agua y obtienes una velocidad nadando igual a tu velocidad caminando. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: crear o destruir agua (1 carga), controlar agua (3 cargas), muro de hielo (3 cargas) o tormenta de hielo (2 cargas).\n\nAnillo de comandar elementales de aire. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de aire. Además, cuando caigas, descenderás 18 m por asalto y no sufrirás daño por la caída. También puedes hablar y entender aurano.\n\nSi ayudas a matar a un elemental de aire mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de relámpago. • Tienes una velocidad volando igual a tu velocidad caminando y puedes levitar. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: muro de viento (1 carga), ráfaga de viento (2 cargas) o relámpago en cadena (3 cargas).\n\nAnillo de comandar elementales de fuego. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de fuego. Además, tienes resistencia al daño de fuego. También puedes hablar y entender ígneo.\n\nSi ayudas a matar a un elemental de fuego mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Eres inmune al daño de fuego. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: bola de fuego (2 cargas), manos ardientes (1 carga) o muro de fuego (3 cargas).\n\nAnillo de comandar elementales de tierra. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de tierra. Además, puedes moverte por terreno difícil compuesto de escombros, rocas o tierra como si fuera terreno normal. También puedes hablar y entender terrano.\n\nSi ayudas a matar a un elemental de tierra mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de ácido. • Puedes moverte a través de tierra sólida o roca como si estas superficies fueran terreno difícil. Si acabas tu turno en ellas, irás a parar al espacio sin ocupar más cercano en el que estuviste por última vez. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: moldear la piedra (2 cargas), muro de piedra (3 cargas) o piel pétrea (3 cargas).\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_78cacd5c998f65d7$::jsonb) union all select 'shared:official:equipment:es:f42e832b6b2895b035bada95' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f42e832b6b2895b035bada95' and payload#>'{description}'=$verify_b3e6b109a5d3d596$"Objeto · Precio base · Peso\nAceite (frasco) · 1 pp · 1 lb\n\nAceite. El aceite suele venir en frascos de arcilla con capacidad para 0,5 l. Como acción, puedes esparcir el aceite de este frasco sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el frasco se rompa con el impacto. En ambos casos, haz un ataque a distancia contra la criatura o el objeto y trata el aceite como un arma improvisada: si tienes éxito, el objetivo quedará cubierto de aceite. Si el objetivo sufre daño de fuego antes de que el aceite se seque (lo que ocurre tras 1 minuto), recibirá 5 de daño de fuego adicional debido al aceite ardiendo. También puedes derramar un frasco de aceite por el suelo, que cubrirá una zona de 1,5 m de lado, siempre y cuando la superficie esté nivelada. Si se prende, el aceite arderá durante 2 asaltos y causará 5 de daño de fuego a cualquier criatura que entre en la zona o acabe su turno en ella. Una criatura solo puede sufrir este daño una vez por turno.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_b3e6b109a5d3d596$::jsonb and payload#>'{features}'=$verify_e92c7a74615a59ed$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Aceite. El aceite suele venir en frascos de arcilla con capacidad para 0,5 l. Como acción, puedes esparcir el aceite de este frasco sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el frasco se rompa con el impacto. En ambos casos, haz un ataque a distancia contra la criatura o el objeto y trata el aceite como un arma improvisada: si tienes éxito, el objetivo quedará cubierto de aceite. Si el objetivo sufre daño de fuego antes de que el aceite se seque (lo que ocurre tras 1 minuto), recibirá 5 de daño de fuego adicional debido al aceite ardiendo. También puedes derramar un frasco de aceite por el suelo, que cubrirá una zona de 1,5 m de lado, siempre y cuando la superficie esté nivelada. Si se prende, el aceite arderá durante 2 asaltos y causará 5 de daño de fuego a cualquier criatura que entre en la zona o acabe su turno en ella. Una criatura solo puede sufrir este daño una vez por turno.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_e92c7a74615a59ed$::jsonb and payload#>'{rules,definition,description}'=$verify_203958f9770774af$[{"id":"official-table","rows":[["Aceite (frasco)","1 pp","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Aceite. El aceite suele venir en frascos de arcilla con capacidad para 0,5 l. Como acción, puedes esparcir el aceite de este frasco sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el frasco se rompa con el impacto. En ambos casos, haz un ataque a distancia contra la criatura o el objeto y trata el aceite como un arma improvisada: si tienes éxito, el objetivo quedará cubierto de aceite. Si el objetivo sufre daño de fuego antes de que el aceite se seque (lo que ocurre tras 1 minuto), recibirá 5 de daño de fuego adicional debido al aceite ardiendo. También puedes derramar un frasco de aceite por el suelo, que cubrirá una zona de 1,5 m de lado, siempre y cuando la superficie esté nivelada. Si se prende, el aceite arderá durante 2 asaltos y causará 5 de daño de fuego a cualquier criatura que entre en la zona o acabe su turno en ella. Una criatura solo puede sufrir este daño una vez por turno.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_203958f9770774af$::jsonb) union all select 'shared:official:equipment:es:f49a0cb0ee5dc6d777c153e6' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f49a0cb0ee5dc6d777c153e6' and payload#>'{features}'=$verify_c69fa0a6289d9a0c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tendrás una velocidad nadando de 12 m mientras lleves puesto este anillo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_c69fa0a6289d9a0c$::jsonb) union all select 'shared:official:equipment:es:f556e8c6ca30b75eb5527eed' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f556e8c6ca30b75eb5527eed' and payload#>'{features}'=$verify_5814ac690fd19565$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Las piedras Ioun se llaman así por Ioun, un dios del conocimiento y la profecía adorado en algunos mundos. Existen muchos tipos de piedras Ioun, cada uno de ellos con una combinación distinta de forma y color.\n\nCuando utilices una acción para lanzar una de estas piedras al aire, la piedra girará alrededor de tu cabeza a una distancia de 1d3 × 30 cm y te otorgará un beneficio. A partir de entonces, otra criatura deberá utilizar una acción para agarrar o atrapar la piedra y separarla de ti, ya sea superando una tirada de ataque contra una CA de 24 o una prueba de Destreza (Acrobacias) con CD 24. Puedes utilizar una acción para tomar y guardar la piedra, lo que pone fin a su efecto.\n\nUna piedra tiene una CA de 24, 10 puntos de golpe y resistencia a todo el daño. Se considera un objeto vestido mientras gira alrededor de tu cabeza.\n\nAbsorción mayor (legendaria). Mientras este elipsoide jaspeado en tonos lilas y verdes gire alrededor de tu cabeza, podrás usar tu reacción para cancelar un conjuro de nivel 8 o inferior lanzado por una criatura que puedas ver y que solo te haga objetivo a ti.\n\nEn cuanto la piedra haya cancelado 50 niveles de conjuros, se volverá gris porque su magia se habrá agotado. Si eres el objetivo de un conjuro cuyo nivel sea superior a la cantidad de niveles de conjuro que le queden a la piedra, no podrá cancelarlo.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_5814ac690fd19565$::jsonb) union all select 'shared:official:equipment:es:f59d76529bbbad4366ef31ef' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f59d76529bbbad4366ef31ef' and payload#>'{features}'=$verify_ac2241f28b1fb2ca$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta gema contiene vestigios de energía elemental. Cuando uses una acción para romperla, invocarás a un elemental como si hubieras lanzado conjurar elemental y la magia de la gema se perderá. El tipo de gema determina el elemental invocado por el conjuro.\n\nEsmeralda · Elemental de agua\nZafiro azul · Elemental de aire\nCorindón rojo · Elemental de fuego\nDiamante amarillo · Elemental de tierra\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_ac2241f28b1fb2ca$::jsonb) union all select 'shared:official:equipment:es:f6074a2c384a012868bc89f1' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f6074a2c384a012868bc89f1' and payload#>'{features}'=$verify_78f99b668bd01213$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras arda incienso en este recipiente, podrás utilizar una acción para pronunciar su palabra de activación e invocar un elemental de aire, como si hubieras lanzado conjurar elemental. El incensario no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nEste recipiente de 15 cm de ancho y 30 cm de alto se parece a un cáliz con una tapa decorativa y pesa 0,5 kg.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_78f99b668bd01213$::jsonb) union all select 'shared:official:equipment:es:f6aefab76047c5788d5cb069' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f6aefab76047c5788d5cb069' and payload#>'{features}'=$verify_821a5098f9124bf9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta arma mágica tiene 3 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 carga para desatar una ola de terror. Todas las criaturas de tu elección situadas en un radio de 9 m respecto a ti deberán superar una tirada de salvación de Sabiduría con CD 15 o quedarán asustadas de ti durante 1 minuto. Una criatura asustada de esta manera deberá dedicar sus turnos a tratar de alejarse de ti todo lo que pueda y no podrá acercarse voluntariamente a ningún espacio que se encuentre a 9 m o menos de ti. Tampoco podrá llevar a cabo reacciones. Tan solo podrá realizar la acción de correr o intentar escapar de un efecto que le impida moverse. Si no tiene adónde ir, la criatura podrá usar la acción de esquivar. Al final de cada uno de sus turnos, la criatura podrá repetir la tirada de salvación y, si tiene éxito, se librará del efecto.\n\nLa maza recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_821a5098f9124bf9$::jsonb) union all select 'shared:official:equipment:es:f6f7ba7d85aced20808b7e36' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f6f7ba7d85aced20808b7e36' and payload#>'{features}'=$verify_b28931322dcf9526$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este pequeño paquete contiene 1d6 + 4 pizcas de polvo. Puedes utilizar una acción para echar una pizca sobre el agua. El polvo convertirá un cubo de agua de 4,5 m de lado en una bolita del tamaño de una canica, que quedará flotando o en reposo cerca de donde se esparció el polvo. El peso de la bolita es insignificante.\n\nCualquier criatura puede utilizar una acción para golpear la bolita contra una superficie dura, lo que hará añicos la bolita y liberará el agua que absorbió el polvo. Hacer esto acaba con la magia de la bolita.\n\nUn elemental compuesto principalmente por agua y que se exponga a una pizca del polvo deberá realizar una tirada de salvación de Constitución con CD 13; sufrirá 10d6 de daño necrótico si la falla o la mitad del daño si la supera.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_b28931322dcf9526$::jsonb) union all select 'shared:official:equipment:es:f76998ec59eb6db8507dc857' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f76998ec59eb6db8507dc857' and payload#>'{features}'=$verify_8e93aec94e5aa892$[{"id":"lance-special","kind":"other","name":"Uso de la lanza de caballería","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.\n\nRequiere dos manos si no se está montado.\n\nDuración: Mientras se utiliza el arma..","showInActions":false},{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":1,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_8e93aec94e5aa892$::jsonb and payload#>'{rules,definition,description}'=$verify_ec7af47f958e8789$[{"id":"official-base-table","rows":[["Lanza de caballería","10 po","6 lb","1d12 perforante","+0","Gran alcance, Especial"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-reach","text":"Gran alcance. Cuando empleas un arma de este tipo, tu alcance aumenta en 1,5 m, tanto al atacar como a efectos de ataques de oportunidad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-special","text":"Especial. Un arma con esta propiedad posee ciertas reglas inusuales que afectan a su uso, tal y como se explica en la descripción del arma (consulta “Armas especiales” en esta misma sección).","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"lance-special","text":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$verify_ec7af47f958e8789$::jsonb) union all select 'shared:official:equipment:es:f7cc21b1535dd5ae98118d7b' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f7cc21b1535dd5ae98118d7b' and payload#>'{features}'=$verify_ae23ed56aa8fbde8$[{"id":"official-use","kind":"passive","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras calces estas botas, tus pasos no harán ruido, independientemente de la superficie que pises. También tendrás ventaja en las pruebas de Destreza (Sigilo) que requieran moverse sin hacer ruido.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_ae23ed56aa8fbde8$::jsonb) union all select 'shared:official:equipment:es:f88e54bf8b39875147baef8e' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f88e54bf8b39875147baef8e' and payload#>'{description}'=$verify_f74e82d3c7405be2$"Objeto · Precio base · Peso\nÁbaco · 2 po · 2 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_f74e82d3c7405be2$::jsonb and payload#>'{rules,definition,description}'=$verify_89f2a195eae4b3f6$[{"id":"official-table","rows":[["Ábaco","2 po","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_89f2a195eae4b3f6$::jsonb) union all select 'shared:official:equipment:es:f9667e4c34019878374a5f6c' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f9667e4c34019878374a5f6c' and payload#>'{features}'=$verify_e4aafe448d73b53f$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este prisma tiene 50 cargas. Mientras lo sostienes, puedes usar una acción para pronunciar una de las tres palabras de activación y causar uno de los siguientes efectos: • La primera palabra de activación hace que la gema emita luz brillante en un radio de 9 m y luz tenue 9 m más allá. Este efecto no gasta una carga. Dura hasta que utilices una acción adicional para repetir la palabra de activación o hasta que emplees otra función de la gema. • La segunda palabra de activación gasta 1 carga y hace que la gema dispare un rayo brillante de luz contra una criatura que puedas ver a 18 m o menos de ti. La criatura deberá superar una tirada de salvación de Constitución con CD 15 o quedará cegada durante 1 minuto. La criatura puede repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto. • La tercera palabra de activación gasta 5 cargas y hace que la gema refulja con una luz cegadora que se extiende en un cono de 9 m. Todas las criaturas situadas en el cono deberán realizar una tirada de salvación como si les hubiera afectado el rayo creado por la segunda palabra de activación. Cuando todas las cargas de la gema se gasten, se convertirá en una joya no mágica con un valor de 50 po.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_e4aafe448d73b53f$::jsonb) union all select 'shared:official:equipment:es:f97aac9925b409067faa06fa' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:f97aac9925b409067faa06fa' and payload#>'{features}'=$verify_1a039f41f1524ec3$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta mochila posee un bolsillo central y dos laterales, cada uno de los cuales es un espacio extradimensio- nal. Cada bolsillo lateral puede contener hasta 10 kg de materia sin exceder un volumen de 0,06 m3. En el bolsillo central caben hasta 0,2 m3 o 40 kg de materia. El morral pesa siempre 2,5 kg, independientemente del contenido.\n\nMeter un objeto en su interior sigue las reglas normales de interacción con objetos. Sacar un objeto del morral cuesta una acción. Cuando metes la mano para extraer un objeto concreto, la magia hará que siempre se encuentre arriba del todo.\n\nEl morral tiene algunas limitaciones. Si se sobrecarga o si un objeto afilado lo perfora o rasga, se romperá y quedará destruido. Si se destruye, su contenido se perderá para siempre, aunque los artefactos siempre volverán a aparecer en alguna parte. Si se pone el morral del revés, su contenido se vuelca sin sufrir daño y el morral debe volver a ponerse del derecho antes de usarlo de nuevo. Si se mete dentro del morral a una criatura que necesite respirar, podrá sobrevivir durante 10 minutos; después, empezará a ahogarse.\n\nMeter el morral en el espacio extradimensional creado por una bolsa de contención, un agujero portátil o un objeto similar destruye instantánea- mente ambos objetos y abre un portal al Plano Astral. El portal se crea en el sitio en el que un objeto se introdujo dentro del otro. El portal absorbe a todas las criaturas que estén a 3 m o menos de él y las conduce a un lugar aleatorio del Plano Astral. Después, el portal se cierra. El portal solo funciona en un sentido y no puede volverse a abrir.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_1a039f41f1524ec3$::jsonb) union all select 'shared:official:equipment:es:fa694e0f28f6a842eb8b74ef' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:fa694e0f28f6a842eb8b74ef' and payload#>'{features}'=$verify_728ec3067b81e280$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 3 cargas. Mientras la empuñes, puedes usar una acción para gastar 1 de sus cargas y, si hay alguna trampa o puerta secreta situada a 9 m o menos de ti, la varita vibrará y apuntará a la más cercana. La varita recupera 1d3 cargas empleadas cada día, al amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_728ec3067b81e280$::jsonb) union all select 'shared:official:equipment:es:fa9ba84b33858e33bab59e7c' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:fa9ba84b33858e33bab59e7c' and payload#>'{description}'=$verify_ec6a0b5ccfcad873$"Objeto · Precio base · Peso\nTinta (frasco de 1 onza) · 10 po · —\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_ec6a0b5ccfcad873$::jsonb and payload#>'{rules,definition,description}'=$verify_28e7ba60fe4c14da$[{"id":"official-table","rows":[["Tinta (frasco de 1 onza)","10 po","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_28e7ba60fe4c14da$::jsonb) union all select 'shared:official:equipment:es:fc008783161bef8547e593aa' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:fc008783161bef8547e593aa' and payload#>'{description}'=$verify_a8c011a0d5114d92$"Objeto · Precio base · Peso\nJuego de dados · 1 pp · —\n\nJuegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_a8c011a0d5114d92$::jsonb and payload#>'{features}'=$verify_39ce10f378e10021$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Juegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_39ce10f378e10021$::jsonb and payload#>'{rules,definition,description}'=$verify_3ec1f6f63d132ac1$[{"id":"official-table","rows":[["Juego de dados","1 pp","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Juegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$verify_3ec1f6f63d132ac1$::jsonb) union all select 'shared:official:equipment:es:fdc90a46759c54f9de9bdfd3' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:fdc90a46759c54f9de9bdfd3' and payload#>'{features}'=$verify_585a0a0b0278bdd6$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este deslumbrante yelmo tiene incrustados 1d10 diamantes, 2d10 rubíes, 3d10 ópalos de fuego y 4d10 ópalos. Cualquier gema que se retire del yelmo se convierte en polvo. Si se retiran o se destruyen todas las gemas, el yelmo pierde su magia.\n\nMientras lo lleves puesto, obtienes lo siguientes beneficios: • Puedes usar una acción para lanzar uno de los siguientes conjuros (CD de salvación 18) usando una de las gemas del yelmo del tipo especificado como componente: bola de fuego (ópalo de fuego), luz del día (ópalo), muro de fuego (rubí) o rociada prismática (diamante). La gema se destruye cuando el conjuro se lanza, por lo que desaparecerá del yelmo. • Mientras quede al menos un diamante, el yelmo emitirá luz tenue en un radio de 9 m si hay por lo menos un muerto viviente en esa zona. Cualquier muerto viviente que comience su turno en la zona sufrirá 1d6 de daño radiante. • Mientras quede al menos un rubí en el yelmo, tendrás resistencia al daño de fuego. • Mientras quede al menos un ópalo de fuego en el yelmo, podrás utilizar una acción para pronunciar una palabra de activación y hacer que un arma que estés empuñando se envuelva en llamas. Las llamas emitirán luz brillante en un radio de 3 m y luz tenue 3 m más allá. Las llamas son inofensivas para ti y el arma. Cuando impactes con un ataque usando el arma llameante, el objetivo recibirá 1d6 de daño de fuego adicional. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o guardes el arma.\n\nTira 1d20 si llevas el yelmo puesto y sufre daño de fuego por haber fallado una tirada de salvación contra un conjuro. Si sacas un 1, las gemas restantes del yelmo emitirán rayos de luz. Salvo tú, todas las criaturas a 18 m o menos del yelmo deberán superar una tirada de salvación de Destreza con CD 17 o un rayo impactará contra ellas y sufrirán una cantidad de daño radiante igual al número de gemas del yelmo. A continuación, el yelmo y sus gemas se destruirán.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_585a0a0b0278bdd6$::jsonb) union all select 'shared:official:equipment:es:fe7e7b105892cbe04c051592' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:fe7e7b105892cbe04c051592' and payload#>'{features}'=$verify_3977514cdc94d6b7$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta joya tiene 3 cargas. Como acción, puedes pronunciar la palabra de activación de la gema y gastar 1 carga. Durante los siguientes 10 minutos, tendrás visión verdadera hasta 36 m si miras a través de la gema.\n\nLa gema recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_3977514cdc94d6b7$::jsonb) union all select 'shared:official:equipment:es:fedd698066b62346698b608a' as failed where not exists(select 1 from public.official_content_entries where kind='equipment' and content_key='official:equipment:es:fedd698066b62346698b608a' and payload#>'{features}'=$verify_54a737b808cf4ff1$[{"id":"restrain-target","kind":"other","name":"Apresar con la red","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Red. Una criatura Grande o más pequeña que sea impactada por una red quedará apresada hasta ser liberada. Esta arma no tendrá efecto sobre objetivos sin forma definida o que sean de tamaño Enorme o mayor. Una criatura puede emplear su acción para hacer una prueba de Fuerza con CD 10. Si tiene éxito, podrá liberarse a sí misma o a otra criatura dentro de su alcance. Infligir 5 de daño cortante a la red (CA 10) también liberará a la criatura sin causarle daño alguno, pondrá fin al efecto y destruirá la red. Cuando utilices una acción, una acción adicional o una reacción para atacar con una red, solo podrás realizar un ataque, incluso aunque normalmente pudieras hacer más de uno.\n\nSolo un ataque por acción, acción adicional o reacción. Liberar con acción y Fuerza CD 10, o destruir la red (CA 10) con 5 de daño cortante. No se inflige ese daño a la criatura.\n\nDuración: Hasta ser liberada.\n\nAlcance: 5/15 pies.","showInActions":false}]$verify_54a737b808cf4ff1$::jsonb) union all select 'inventory:inv_12f1ec5a1cb0ebb47f63bf0f4f6d9732' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_12f1ec5a1cb0ebb47f63bf0f4f6d9732' and payload#>'{description}'=$verify_6fbb8ca207152d72$"Armadura de Campo Korr\nObjeto Raro\nBasada en Armadura +1\n\nHistoria\nDraven construyó esta armadura durante años.\nLa estructura incorpora:\nacero sureño;\npiezas recuperadas de ruinas;\nfragmentos de cristal luciente refinado.\nNo es tecnología aeloriana.\nPero representa el primer intento moderno de imitarla.\n\nBeneficios\nCA incluida en el cálculo.\nResistencia excepcional."$verify_6fbb8ca207152d72$::jsonb and payload#>'{features}'=$verify_da6d92a85c5ac3d8$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Armadura de Campo Korr\nObjeto Raro\nBasada en Armadura +1\n\nHistoria\nDraven construyó esta armadura durante años.\nLa estructura incorpora:\nacero sureño;\npiezas recuperadas de ruinas;\nfragmentos de cristal luciente refinado.\nNo es tecnología aeloriana.\nPero representa el primer intento moderno de imitarla.\n\nBeneficios\nCA incluida en el cálculo.\nResistencia excepcional.","showInActions":false}]$verify_da6d92a85c5ac3d8$::jsonb and payload#>'{rules,definition,description}'=$verify_7ab462ea23d4b0ae$[{"id":"recovered-campaign-description","text":"Armadura de Campo Korr\nObjeto Raro\nBasada en Armadura +1\n\nHistoria\nDraven construyó esta armadura durante años.\nLa estructura incorpora:\nacero sureño;\npiezas recuperadas de ruinas;\nfragmentos de cristal luciente refinado.\nNo es tecnología aeloriana.\nPero representa el primer intento moderno de imitarla.\n\nBeneficios\nCA incluida en el cálculo.\nResistencia excepcional.","type":"paragraph","section":"flavor","sourceIds":["ece-campaign-document"],"provenance":"campaign"}]$verify_7ab462ea23d4b0ae$::jsonb and payload#>'{catalog,revision}'=$verify_6b86b273ff34fce1$1$verify_6b86b273ff34fce1$::jsonb and revision=2) union all select 'inventory:inv_15542c5cbb844f6c665aa92505534567' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_15542c5cbb844f6c665aa92505534567' and payload#>'{description}'=$verify_569cb37696c7d3eb$"Objeto · Precio base · Peso\nHerramientas de cartógrafo · 15 po · 6 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_569cb37696c7d3eb$::jsonb and payload#>'{features}'=$verify_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_2b2bca0e5c7a5789$::jsonb and payload#>'{rules,definition,description}'=$verify_08ae83fa509ef72d$[{"id":"official-table","rows":[["Herramientas de cartógrafo","15 po","6 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$verify_08ae83fa509ef72d$::jsonb and payload#>'{catalog,revision}'=$verify_4b227777d4dd1fc6$4$verify_4b227777d4dd1fc6$::jsonb and revision=3) union all select 'inventory:inv_17d70437e6fcbbd187008753b2f69ee1' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind=